<?php declare(strict_types=1); namespace App\Modules\Tourism\Controllers; use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use RuntimeException;use Throwable;use App\Modules\Tourism\Services\TourismExperienceService; final class TourismExperienceController extends Controller{private TourismExperienceService $s;private Authorization $a;public function __construct(){$this->s=new TourismExperienceService();$this->a=new Authorization();}private function allow($p,$r='/tourism'){try{$this->a->authorize($p);return true;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect($r);return false;}}private function data($t){return ['providers'=>$this->s->providers($t),'destinations'=>$this->s->destinations($t)];}public function index(){if(!$this->allow('tourism.experiences.view'))return;$t=(int)Auth::tenantId();$trash=($_GET['view']??'')==='trash';$this->view('Tourism::Experiences.index',['title'=>$trash?'Deleted Experiences':'Tourism Experiences','experiences'=>$this->s->all($t,$trash),'trash'=>$trash]);}public function create(){if(!$this->allow('tourism.experiences.create','/tourism/experiences'))return;$this->view('Tourism::Experiences.create',array_merge(['title'=>'Add Experience'],$this->data((int)Auth::tenantId())));}public function store(){if(!$this->allow('tourism.experiences.create','/tourism/experiences'))return;$t=(int)Auth::tenantId();try{$id=$this->s->save($t,null,$_POST,(int)Auth::id());flash('success','Experience created.');redirect('/tourism/experiences/'.$id);}catch(Throwable $e){$this->view('Tourism::Experiences.create',array_merge(['title'=>'Add Experience','error'=>$e->getMessage(),'old'=>$_POST],$this->data($t)));}}public function show($id){if(!$this->allow('tourism.experiences.view','/tourism/experiences'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('Tourism::Experiences.show',['title'=>$r['title'],'record'=>$r]);}public function edit($id){if(!$this->allow('tourism.experiences.edit','/tourism/experiences'))return;$t=(int)Auth::tenantId();$r=$this->s->find($t,$id);if(!$r)abort(404);$this->view('Tourism::Experiences.edit',array_merge(['title'=>'Edit Experience','record'=>$r],$this->data($t)));}public function update($id){if(!$this->allow('tourism.experiences.edit','/tourism/experiences'))return;$t=(int)Auth::tenantId();try{$this->s->update($t,$id,$_POST,(int)Auth::id());flash('success','Experience updated.');redirect('/tourism/experiences/'.$id);}catch(Throwable $e){$this->view('Tourism::Experiences.edit',array_merge(['title'=>'Edit Experience','record'=>$this->s->find($t,$id)??$_POST,'error'=>$e->getMessage()],$this->data($t)));}}public function destroy($id){if(!$this->allow('tourism.experiences.delete','/tourism/experiences'))return;$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Experience moved to Trash.');redirect('/tourism/experiences');}public function restore($id){if(!$this->allow('tourism.experiences.delete','/tourism/experiences?view=trash'))return;$this->s->restore((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Experience restored.');redirect('/tourism/experiences?view=trash');}}